"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[6617],{4954:e=>{e.exports=JSON.parse('{"tag":{"label":"AI","permalink":"/datagol-knowlegde-base-v1/docs/tags/ai","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":7,"items":[{"id":"AI Agents/About AI agents","title":"About AI agents","description":"The DataGOL AI Agents empowers business users and engineers to efficiently analyze and visualize data through a suite of specialized AI agents. These agents act as intelligent assistants, guiding users through the data exploration process and accelerating insights.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/about-AI-agents"},{"id":"AI Agents/Business Intelligence (BI) agent - (Chart agent)","title":"Business Intelligence (BI) agent - (Chart agent)","description":"BI or Chart agent allows you to visualize data from structured datasets using various chart types and provides insights through graphical representations of data.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/business-intelligence-BI-agent-Chart-agent"},{"id":"AI Agents/Data Cleaning (DC) agent","title":"Data Cleaning (DC) agent","description":"The DC agent helps users to clean and organize their data within a workbook. This includes tasks like deduplication, normalization, data imputation, and filtering.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-cleaning-agent-DCA-agent"},{"id":"AI Agents/Data Conversion Agent (DCA)","title":"Data Conversion Agent (DCA)","description":"The DCA enables users to quickly retrieve and analyze data from workbooks using natural language queries. Moreover, the agent also provides tabular results based on SQL queries.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-conversion-agent"},{"id":"AI Agents/Python Agent","title":"Python Agent","description":"The Python agent is designed to handle more complex data analysis tasks that go beyond basic SQL queries and visualizations. The Python agent is utilized for complex data manipulation tasks that exceed the capabilities of standard SQL queries. Such tasks include generating machine learning code for rapid testing, performing dimensionality reduction using PCA, and conducting anomaly detection with statistical models. Here\'s a breakdown of its purpose and capabilities:","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/python-agent"},{"id":"AI Agents/Retrieval Augmented Generation (RAG) Agent","title":"Retrieval Augmented Generation (RAG) Agent","description":"RAG agents enhance Large Language Models (LLMs) by providing them with access to an external knowledge base, enabling accurate and efficient information retrieval from unstructured data.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/retrieval-augmented-generation-agent-RAG-agent"},{"id":"AI Agents/SQL Agent","title":"SQL Agent","description":"The SQL agent in DataGOL is a tool designed to streamline the process of working with SQL by enabling users to interact with databases using natural language. It goes beyond simple query generation by also offering optimization and debugging capabilities for the created SQL.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/sql-agent"}],"unlisted":false}}')}}]);